grail.canonicalQuery:
fetch dt.entity.service
| filter id == "SERVICE-CBE301375B4AD11E"
| filter entity.name == "adservice"
| lookup 
	[
		timeseries by:{dt.entity.service}, filter:dt.entity.service == "SERVICE-CBE301375B4AD11E", {count = sum(dt.service.request.count), response_time = avg(dt.service.request.response_time), failure_count = sum(dt.service.request.failure_count)}
		| fieldsAdd requests = arraySum(count), latency = arrayAvg(response_time), failures = arraySum(failure_count)
	], sourceField:id, lookupField:dt.entity.service, prefix:"service."
| lookup 
	[
		fetch logs
		| filter dt.entity.service == "SERVICE-CBE301375B4AD11E"
		| summarize by:{dt.entity.service}, {total_logs = count(), error_logs = countIf(status == "ERROR")}
	], sourceField:id, lookupField:dt.entity.service, prefix:"logs."
| lookup 
	[
		timeseries by:{dt.entity.service}, filter:dt.entity.service == "SERVICE-CBE301375B4AD11E", {sum_ad_requests = sum(app.ads.ad_requests), avg_jvm_cpu = avg(process.runtime.jvm.cpu.utilization), avg_jvm_mem = avg(process.runtime.jvm.memory.usage)}
		| fieldsAdd ad_requests = arraySum(sum_ad_requests), jvm_cpu = arrayAvg(avg_jvm_cpu), jvm_mem = arrayAvg(avg_jvm_mem)
	], sourceField:id, lookupField:dt.entity.service, prefix:"metrics."
| fields microservice = entity.name, id, service.requests, service.latency, service.failures, logs.total_logs, logs.error_logs, metrics.ad_requests, metrics.jvm_cpu, metrics.jvm_mem

